declare n int; h text;
begin
  select count(*), md5(string_agg(id::text || '|' || coalesce(source_md5, '') || '|' || status || '|' || coalesce(size_after::text, ''), ',' order by id))
    into n, h from hermes_os.media_optimizer_jobs
   where id in ('59fe8680-c9cb-467c-abdf-248d5a8610bd', '38e84f2e-c1b9-4dae-bc7b-975cc5e4af94', '6acb25ca-30ad-4be5-a73a-a36cb71d3857',
                'e38d26fb-3862-4cde-84f1-b36516f36a51', '804cb2a9-ac3d-419e-8e86-b568d825527a');
  if n <> 5 or h <> '8cf0e1402b91d1e11f86b68878cde7ed' then
    raise exception 'DATA_COPY_CHECK_FAILED n=% md5=%', n, h;
  end if;
end $$;
